// Rebuild adventures/bundle.js so the engine also works when index.html is opened from disk (file://).
// Usage: node tools/bundle.js
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, '..', 'adventures');
const index = JSON.parse(fs.readFileSync(path.join(dir, 'index.json'), 'utf8'));
const bundle = {};
for (const a of index) bundle['adventures/' + a.file] = JSON.parse(fs.readFileSync(path.join(dir, a.file), 'utf8'));
fs.writeFileSync(path.join(dir, 'bundle.js'),
  '// Generated by tools/bundle.js - do not edit. Lets the library work from file:// where fetch() is blocked.\n' +
  'window.GTA_BUNDLE_INDEX = ' + JSON.stringify(index) + ';\nwindow.GTA_BUNDLE = ' + JSON.stringify(bundle) + ';\n');
console.log('bundled', Object.keys(bundle).length, 'adventures');
